// ConfigResponse defines model for ConfigResponse.
type ConfigResponse struct {
	Agents map[string]AgentConfig `json:"agents"`

	// ArtifactConcurrency Max visual-artifact generations that run at once, across foreground (a user viewing a diff) and background (proactive pre-generation) work (artifact_concurrency in config.toml). Generations can be heavy (a full build per ref, RAM-hungry tooling like emulators), so this caps parallelism - lower it for memory-hungry generators. Foreground requests are served before queued background ones; a running generation is never preempted. 0 means unlimited (no cap); null/absent uses the built-in default.
	ArtifactConcurrency *int `json:"artifact_concurrency"`

	// ArtifactPrefetch Whether the daemon proactively pre-generates a head's artifacts in the background once its working tree settles, so a diff is ready before it is opened (artifact_prefetch in config.toml). When false, artifacts are generated only when a diff is viewed; foreground generation and artifact_concurrency still apply. null/absent uses the built-in default (enabled).
	ArtifactPrefetch *bool `json:"artifact_prefetch"`

	// Artifacts Per-project visual-artifact generation scripts ([artifacts.<name>] in config.toml)
	Artifacts *[]ArtifactScript `json:"artifacts"`

	// DefaultPrePrompt Built-in default pre-prompt always prepended to agent prompts (read-only)
	DefaultPrePrompt *string     `json:"default_pre_prompt,omitempty"`
	Defaults         AgentConfig `json:"defaults"`

	// McpServers Read-only: candidate MCP servers discovered in the host ~/.claude.json and project .mcp.json, for populating the mcp_allowed picker. Ignored on save.
	McpServers *[]McpServer `json:"mcp_servers"`

	// NotifyTestFailures Whether a test runner settling FAILING wakes the head with a one-line message ([notify] test_failures in config.toml). It only fires while the head is IDLE, so it cannot interrupt a turn or loop, and it is deduped per (runner, commit). The agent pulls the output with get_test_logs. null/absent uses the built-in default (enabled).
	NotifyTestFailures *bool `json:"notify_test_failures"`

	// Previews Per-project live-server scripts, each proxied on demand as a clickable preview of the head's app ([previews.<name>] in config.toml). A config still spelling one as an [artifacts.<name>] with type = "server" is upgraded on read, so it appears here and not under artifacts.
	Previews *[]PreviewScript `json:"previews"`

	// ResourceCapacity Effective safety ceilings resolved for the server machine and user config. CPU quotas use systemd's percent-of-one-core units (400 = four logical CPUs). Workloads retain explicit [resources] overrides, while machine and background values are aggregate parent-slice ceilings.
	ResourceCapacity ResourceCapacity `json:"resource_capacity"`

	// Resources The raw [resources] cgroup limits for ONE config layer (project / user / local), as edited in the Settings scope tabs. Applied to every scoped workload of the project (agent, preview, service, artifact) via its transient systemd scope. Every field is nullable; a null field is unset at this layer and inherits the layer below. Built-in defaults apply CPU and IO ceilings as well as 50/50 weights; explicit zero disables a hard cap. Weights are soft (bite only under contention); hard caps apply even on an idle box and may be silently skipped where their cgroup controller is not delegated to the user systemd manager.
	Resources *ResourceLimits `json:"resources,omitempty"`

	// Review The raw [review] config for ONE config layer (project / user / local), as edited in the Settings scope tabs. Every field is nullable; a null field is unset at this layer and inherits the layer below (built-in defaults are applied only in the resolved ReviewConfigResponse). Which file a save writes to is chosen by the scope tab, so provider/target/etc. can live in the shared config.toml and personal overrides in config.local.toml.
	Review *ReviewConfig `json:"review,omitempty"`

	// Services Per-project long-running supervised commands ([services.<name>] in config.toml)
	Services *[]ServiceScript `json:"services"`

	// TestConcurrency Max test-runner generations that run at once (test_concurrency in config.toml). 0 = unlimited; null/absent uses the built-in default.
	TestConcurrency *int `json:"test_concurrency"`

	// TestPrefetch Whether the daemon proactively re-runs a head's test suites in the background when its branch-tip verdict is missing or stale (a cached result computed for an older commit), so the verdict is ready before the tests panel is opened or the merge gate runs (test_prefetch in config.toml). When false, tests run only on open / at merge; foreground runs and test_concurrency still apply. null/absent uses the built-in default (enabled).
	TestPrefetch *bool `json:"test_prefetch"`

	// Tests Per-project test-runner commands whose verdict gates merge ([tests.<name>] in config.toml)
	Tests *[]TestScript `json:"tests"`
}

